  });

  test('Get character mining ledger', ({ given, when, then }) => {
    const characterId = 1689391488;
    let result: any;

    given('a character who has been mining', () => {
      const mockLedger = [
        {
          date: '2026-04-22',
          solar_system_id: 30000142,
          type_id: 1230,
          quantity: 15000,
        },
        {
          date: '2026-04-22',
          solar_system_id: 30000142,
          type_id: 1228,
