    then('I should receive daily ore quantities', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(3);
      expect(result[0]).toHaveProperty('date', '2026-04-22');
      expect(result[0]).toHaveProperty('solar_system_id');
      expect(result[0]).toHaveProperty('type_id');
      expect(result[0]).toHaveProperty('quantity');
      expect(result[0].quantity).toBeGreaterThan(0);
    });
  });

  test('Get corporation mining observers', ({ given, when, then }) => {
    const corporationId = 1344654522;
    let result: any;

    given('a corporation with mining observers', () => {
      const mockObservers = [
        {
          observer_id: 1021975535893,
          observer_type: 'structure',
          last_updated: '2026-04-22T12:00:00Z',
        },
        {
          observer_id: 1021975535894,
          observer_type: 'structure',
          last_updated: '2026-04-21T18:00:00Z',
        },
      ];

      jest
        .spyOn(client.industry, 'getCorporationMiningObservers')
        .mockResolvedValue(mockObservers);
    });

    when('I request the observer list', async () => {
      result =
        await client.industry.getCorporationMiningObservers(corporationId);
    });

    then('I should receive observer details', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(2);
      expect(result[0]).toHaveProperty('observer_id');
      expect(result[0]).toHaveProperty('observer_type', 'structure');
      expect(result[0]).toHaveProperty('last_updated');
    });
  });

  test('Get mining observer details', ({ given, when, then }) => {
    const corporationId = 1344654522;
    const observerId = 1021975535893;
    let result: any;

    given('a valid mining observer', () => {
      const mockEntries = [
        {
          character_id: 1689391488,
          recorded_corporation_id: 1344654522,
          type_id: 1230,
          quantity: 50000,
          last_updated: '2026-04-22T12:00:00Z',
        },
        {
          character_id: 123456789,
          recorded_corporation_id: 1344654522,
          type_id: 1228,
          quantity: 30000,
          last_updated: '2026-04-22T11:00:00Z',
        },
      ];

      jest
        .spyOn(client.industry, 'getCorporationMiningObserver')
        .mockResolvedValue(mockEntries);
    });

    when('I request the observer activity', async () => {
      result = await client.industry.getCorporationMiningObserver(
        corporationId,
        observerId,
      );
    });

    then('I should receive character mining entries', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(2);
      expect(result[0]).toHaveProperty('character_id');
      expect(result[0]).toHaveProperty('recorded_corporation_id');
      expect(result[0]).toHaveProperty('type_id');
      expect(result[0]).toHaveProperty('quantity');
      expect(result[0]).toHaveProperty('last_updated');
    });
  });

  test('Unauthorized access to industry jobs', ({ given, when, then }) => {
    const characterId = 1689391488;
    let caughtError: any;

    given('an invalid or expired token', () => {
      const forbiddenError = TestDataFactory.createError(403);

      jest
        .spyOn(client.industry, 'getCharacterIndustryJobs')
        .mockRejectedValue(forbiddenError);
    });

    when('I request character industry jobs', async () => {
      try {
        await client.industry.getCharacterIndustryJobs(characterId);
      } catch (error) {
        caughtError = error;
      }
    });

    then('I should receive a 403 forbidden error for industry jobs', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('Unauthorized access to corporation mining data', ({ given, when, then }) => {
    const corporationId = 1344654522;
    let caughtError: any;

    given('insufficient corporation roles', () => {
      const forbiddenError = TestDataFactory.createError(403);

      jest
        .spyOn(client.industry, 'getCorporationMiningObservers')
        .mockRejectedValue(forbiddenError);
    });

    when('I request mining observers', async () => {
      try {
        await client.industry.getCorporationMiningObservers(corporationId);
      } catch (error) {
        caughtError = error;
      }
    });

    then('I should receive a 403 forbidden error for mining observers', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('Fetch character jobs, facilities, and systems concurrently', ({ given, when, then }) => {
    const characterId = 1689391488;
    let jobs: any;
    let facilities: any;
    let systems: any;

    given('an authenticated character for concurrent industry fetch', () => {
      const mockJobs = [
        TestDataFactory.createIndustryJob({
          job_id: 1000001,
          status: 'active',
        }),
      ];
      const mockFacilities = [
        {
          facility_id: 60003760,
          owner_id: 1000035,
          region_id: 10000002,
          solar_system_id: 30000142,
          tax: 0.1,
          type_id: 35825,
        },
      ];
      const mockSystems = [
        {
          solar_system_id: 30000142,
          cost_indices: [{ activity: 'manufacturing', cost_index: 0.048 }],
        },
      ];

      jest
        .spyOn(client.industry, 'getCharacterIndustryJobs')
        .mockResolvedValue(mockJobs);
      jest
        .spyOn(client.industry, 'getIndustryFacilities')
        .mockResolvedValue(mockFacilities);
      jest
        .spyOn(client.industry, 'getIndustrySystems')
        .mockResolvedValue(mockSystems);
    });

    when('I fetch industry jobs, facilities, and systems in parallel', async () => {
      [jobs, facilities, systems] = await Promise.all([
        client.industry.getCharacterIndustryJobs(characterId),
        client.industry.getIndustryFacilities(),
        client.industry.getIndustrySystems(),
      ]);
    });

    then('all three industry requests should resolve successfully', () => {
      expect(jobs).toBeInstanceOf(Array);
      expect(jobs).toHaveLength(1);
      expect(jobs[0].status).toBe('active');

      expect(facilities).toBeInstanceOf(Array);
      expect(facilities).toHaveLength(1);
      expect(facilities[0].facility_id).toBe(60003760);

      expect(systems).toBeInstanceOf(Array);
      expect(systems).toHaveLength(1);
      expect(systems[0].solar_system_id).toBe(30000142);
    });
  });
});
"}

Write {"file_path":"D:/code/ESI.ts/tests/bdd/step-definitions/core/insurance.steps.ts","content":"import { defineFeature, loadFeature } from 'jest-cucumber';
import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/insurance.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-insurance-client',
      baseUrl: 'https://esi.evetech.net',
      timeout: 5000,
    });
  });

  test('Retrieve insurance prices for all ship types', ({ given, when, then }) => {
    let result: any;

    given('the insurance system is operational', () => {
      const expectedPrices = [
        {
          type_id: 587,
          levels: [
            { cost: 10.0, name: 'Basic', payout: 20.0 },
            { cost: 25.0, name: 'Standard', payout: 50.0 },
            { cost: 50.0, name: 'Bronze', payout: 100.0 },
            { cost: 100.0, name: 'Silver', payout: 200.0 },
            { cost: 200.0, name: 'Gold', payout: 400.0 },
            { cost: 400.0, name: 'Platinum', payout: 800.0 },
          ],
        },
        {
          type_id: 29984,
          levels: [
            { cost: 1000000.0, name: 'Basic', payout: 2000000.0 },
            { cost: 2500000.0, name: 'Standard', payout: 5000000.0 },
            { cost: 5000000.0, name: 'Bronze', payout: 10000000.0 },
            { cost: 10000000.0, name: 'Silver', payout: 20000000.0 },
            { cost: 20000000.0, name: 'Gold', payout: 40000000.0 },
            { cost: 40000000.0, name: 'Platinum', payout: 80000000.0 },
          ],
        },
      ];

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockResolvedValue(expectedPrices);
    });

    when('I request insurance prices', async () => {
      result = await client.insurance.getInsurancePrices();
    });

    then('I should receive pricing data for available ship types', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result.length).toBeGreaterThan(0);
      expect(result[0]).toHaveProperty('type_id');
      expect(result[0]).toHaveProperty('levels');
      expect(result[0].levels).toBeInstanceOf(Array);
      expect(result[0].levels[0]).toHaveProperty('cost');
      expect(result[0].levels[0]).toHaveProperty('name');
      expect(result[0].levels[0]).toHaveProperty('payout');
    });
  });

  test('Verify insurance price tiers are ordered correctly', ({ given, when, then }) => {
    let levels: any;

    given('insurance prices are available for tier verification', () => {
      const shipPrices = [
        {
          type_id: 24690,
          levels: [
            { cost: 500000.0, name: 'Basic', payout: 1000000.0 },
            { cost: 1250000.0, name: 'Standard', payout: 2500000.0 },
            { cost: 2500000.0, name: 'Bronze', payout: 5000000.0 },
            { cost: 5000000.0, name: 'Silver', payout: 10000000.0 },
            { cost: 10000000.0, name: 'Gold', payout: 20000000.0 },
            { cost: 20000000.0, name: 'Platinum', payout: 40000000.0 },
          ],
        },
      ];

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockResolvedValue(shipPrices);
    });

    when('I examine the tiers for a ship type', async () => {
      const result = await client.insurance.getInsurancePrices();
      levels = result[0].levels;
    });

    then('higher tiers should have increasing costs and payouts', () => {
      for (let i = 1; i < levels.length; i++) {
        expect(levels[i].cost).toBeGreaterThan(levels[i - 1].cost);
        expect(levels[i].payout).toBeGreaterThan(levels[i - 1].payout);
      }
    });
  });

  test('Verify payout always exceeds cost for each tier', ({ given, when, then }) => {
    let result: any;

    given('insurance prices are available for payout verification', () => {
      const shipPrices = [
        {
          type_id: 17918,
          levels: [
            { cost: 3000000.0, name: 'Basic', payout: 6000000.0 },
            { cost: 7500000.0, name: 'Standard', payout: 15000000.0 },
            { cost: 15000000.0, name: 'Bronze', payout: 30000000.0 },
            { cost: 30000000.0, name: 'Silver', payout: 60000000.0 },
            { cost: 60000000.0, name: 'Gold', payout: 120000000.0 },
            { cost: 120000000.0, name: 'Platinum', payout: 240000000.0 },
          ],
        },
      ];

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockResolvedValue(shipPrices);
    });

    when('I check each tier', async () => {
      result = await client.insurance.getInsurancePrices();
    });

    then('the payout should always be greater than the cost', () => {
      result.forEach((ship: any) => {
        ship.levels.forEach((level: any) => {
          expect(level.payout).toBeGreaterThan(level.cost);
        });
      });
    });
  });

  test('Handle large insurance dataset', ({ given, when, then }) => {
    let result: any;
    let startTime: number;
    let endTime: number;

    given('a large insurance dataset covering many ship types', () => {
      const largeDataset = Array.from({ length: 500 }, (_, i) => ({
        type_id: 1000 + i,
        levels: [
          { cost: 100.0 * (i + 1), name: 'Basic', payout: 200.0 * (i + 1) },
          {
            cost: 250.0 * (i + 1),
            name: 'Standard',
            payout: 500.0 * (i + 1),
          },
          {
            cost: 500.0 * (i + 1),
            name: 'Bronze',
            payout: 1000.0 * (i + 1),
          },
          {
            cost: 1000.0 * (i + 1),
            name: 'Silver',
            payout: 2000.0 * (i + 1),
          },
          {
            cost: 2000.0 * (i + 1),
            name: 'Gold',
            payout: 4000.0 * (i + 1),
          },
          {
            cost: 4000.0 * (i + 1),
            name: 'Platinum',
            payout: 8000.0 * (i + 1),
          },
        ],
      }));

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockResolvedValue(largeDataset);
    });

    when('I process the large insurance response', async () => {
      startTime = Date.now();
      result = await client.insurance.getInsurancePrices();
      endTime = Date.now();
    });

    then('the system should handle it efficiently', () => {
      expect(result.length).toBe(500);
      expect(endTime - startTime).toBeLessThan(1000);
      expect(result.every((item: any) => item.levels.length === 6)).toBe(
        true,
      );
    });
  });

  test('Each ship type has exactly six insurance tiers', ({ given, when, then }) => {
    let result: any;
    const expectedTierNames = [
      'Basic',
      'Standard',
      'Bronze',
      'Silver',
      'Gold',
      'Platinum',
    ];

    given('insurance prices are available for tier count verification', () => {
      const prices = [
        {
          type_id: 587,
          levels: expectedTierNames.map((name, i) => ({
            cost: 10.0 * Math.pow(2, i),
            name,
            payout: 20.0 * Math.pow(2, i),
          })),
        },
        {
          type_id: 24690,
          levels: expectedTierNames.map((name, i) => ({
            cost: 500000.0 * Math.pow(2, i),
            name,
            payout: 1000000.0 * Math.pow(2, i),
          })),
        },
      ];

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockResolvedValue(prices);
    });

    when('I inspect each ship type', async () => {
      result = await client.insurance.getInsurancePrices();
    });

    then('every entry should contain six named tiers', () => {
      result.forEach((entry: any) => {
        expect(entry.levels.length).toBe(6);
        const tierNames = entry.levels.map((l: any) => l.name);
        expect(tierNames).toEqual(expectedTierNames);
      });
    });
  });

  test('Handle ESI service unavailable error', ({ given, when, then }) => {
    let caughtError: any;

    given('the ESI service is temporarily unavailable', () => {
      const serviceError = TestDataFactory.createError(503);

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockRejectedValue(serviceError);
    });

    when('I request insurance prices expecting an error', async () => {
      try {
        await client.insurance.getInsurancePrices();
      } catch (error) {
        caughtError = error;
      }
    });

    then('I should receive a 503 service unavailable error', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('Handle rate limiting on insurance endpoint', ({ given, when, then }) => {
    let caughtError: any;

    given('the API rate limit has been exceeded', () => {
      const rateLimitError = TestDataFactory.createError(429);

      jest
        .spyOn(client.insurance, 'getInsurancePrices')
        .mockRejectedValue(rateLimitError);
    });

    when('I request insurance prices expecting rate limit error', async () => {
      try {
        await client.insurance.getInsurancePrices();
      } catch (error) {
        caughtError = error;
      }
    });

    then('I should receive a 429 rate limit error', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });
});
"}

